/**
 * Multipart. Accepts drag-drop, file picker **and clipboard paste** — paste
is what decides whether support agents actually attach screenshots.

Validated by extension allow-list **and** MIME sniffing — the extension
alone is trivially wrong. EXIF is stripped, the file is virus-scanned, and
it becomes visible only after the scan passes. Stored at
`tickets/{ticketId}/{uuid}`; downloads use short-lived signed URLs and the
bucket is never public.

Limits, all configurable: 10 MB per file, 50 MB and 20 files per ticket.

 * @summary Upload an attachment
 */
export const uploadAttachment = (
    ticketId: string,
    uploadAttachmentBody: UploadAttachmentBody,
 signal?: AbortSignal
) => {
      
      const formData = new FormData();
formData.append(`file`, uploadAttachmentBody.file)
if(uploadAttachmentBody.isClientVisible !== undefined) {
 formData.append(`isClientVisible`, uploadAttachmentBody.isClientVisible.toString())
 }
if(uploadAttachmentBody.commentId !== undefined) {
 formData.append(`commentId`, uploadAttachmentBody.commentId.toString())
 }

      return http<AttachmentResponse>(
      {url: `/tickets/${ticketId}/attachments`, method: 'POST',
      headers: {'Content-Type': 'multipart/form-data', },
       data: formData, signal
    },
      );
    }
  


